<?php
require 'includes/bootstrap.php';if(!is_admin()){http_response_code(403);exit('Admin access required.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$u=post_str('username',60);$name=post_str('full_name',150);$pass=(string)($_POST['password']??'');$role=$_POST['role']??'cashier';$br=(int)($_POST['branch_id']??$branchId);if(!in_array($role,['admin','pharmacist','cashier','storekeeper'],true))$role='cashier';
 if(strlen($pass)<12){flash('error','Password must contain at least 12 characters.');redirect('users.php');}
 try{$s=$pdo->prepare('INSERT INTO users(username,full_name,password_hash,role,branch_id) VALUES(?,?,?,?,?)');$s->execute([$u,$name,password_hash($pass,PASSWORD_DEFAULT),$role,$br]);audit($pdo,'user.created',$u.' '.$role);flash('success','User created.');}catch(PDOException $e){flash('error','Could not create user. Username may already exist.');}redirect('users.php');}
$users=$pdo->query('SELECT u.id,u.username,u.full_name,u.role,u.active,b.name branch FROM users u LEFT JOIN branches b ON b.id=u.branch_id ORDER BY u.id')->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches WHERE active=1')->fetchAll();page_header('User management');
?><section class="panel"><h2>Create user</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div><label>Username</label><input name="username" required></div><div><label>Full name</label><input name="full_name" required></div><div><label>Temporary password (12+ chars)</label><input type="password" name="password" minlength="12" required></div><div><label>Role</label><select name="role"><option>cashier</option><option>pharmacist</option><option>storekeeper</option><option>admin</option></select></div><div><label>Branch</label><select name="branch_id"><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=e($b['name'])?></option><?php endforeach?></select></div><div><button>Create user</button></div></div></form></section>
<section class="panel"><h2>Existing users</h2><div class="table-wrap"><table><tr><th>Username</th><th>Name</th><th>Role</th><th>Branch</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['full_name'])?></td><td><?=e($u['role'])?></td><td><?=e($u['branch']??'—')?></td><td><?=$u['active']?'Active':'Disabled'?></td></tr><?php endforeach?></table></div></section><?php page_footer();?>
